 1	method IsGreater(n: int, a: array<int>) returns (result: bool)
 2	    requires a != null
 3	    ensures result ==> forall i :: 0 <= i < a.Length ==> n > a[i]
 4	    ensures !result ==> exists i :: 0 <= i < a.Length && n <= (a[i]) - 1
 5	{
 6	    result := true;
 7	    var i := 0;
 8	    while i < a.Length
 9	        invariant 0 <= i <= a.Length
10	        invariant result ==> forall k :: 0 <= k < i ==> n > a[k]
11	        invariant !result ==> exists k :: 0 <= k < i && n <= a[k]
12	    {
13	        if n <= a[i] {
14	            result := false;
15	            break;
16	        }
17	        i := i + 1;
18	    }
19	}

